import { render } from '@solidjs/web';
import {
  createMemo,
  action,
  affects,
  refresh,
  Loading,
  isPending,
} from 'solid-js';

function createAPI() {
  let total = 0;
  return {
    async read() {
      await new Promise((resolve) => setTimeout(resolve, 80));
      return total;
    },
    async increment(fail = false) {
      await new Promise((resolve) => setTimeout(resolve, 600));
      if (fail)
        throw new Error('Save failed; the optimistic change was rolled back.');
      total += 1;
    },
  };
}

function App() {
  const api = createAPI();
  const count = createMemo(() => api.read());
  const increment = action(function* () {
    // Declare the affected reader.
    yield api.increment();
    // Refresh after the write finishes.
  });
  return (
    <Loading fallback={<p>Loading counter...</p>}>
      <p>Server count: {count()}</p>
      <button
        disabled={isPending(count)}
        onClick={() => {
          void increment().catch(console.error);
        }}
      >
        Increment server
      </button>
      <p role="status">
        {isPending(count) ? 'Server value changing...' : 'Up to date'}
      </p>
    </Loading>
  );
}

render(() => <App />, document.getElementById('app'));

import { render } from '@solidjs/web';
import {
  createMemo,
  action,
  affects,
  refresh,
  Loading,
  isPending,
} from 'solid-js';

function createAPI() {
  let total = 0;
  return {
    async read() {
      await new Promise((resolve) => setTimeout(resolve, 80));
      return total;
    },
    async increment(fail = false) {
      await new Promise((resolve) => setTimeout(resolve, 600));
      if (fail)
        throw new Error('Save failed; the optimistic change was rolled back.');
      total += 1;
    },
  };
}

function App() {
  const api = createAPI();
  const count = createMemo(() => api.read());
  const increment = action(function* () {
    affects(count);
    yield api.increment();
    yield refresh(count);
  });
  return (
    <Loading fallback={<p>Loading counter...</p>}>
      <p>Server count: {count()}</p>
      <button
        disabled={isPending(count)}
        onClick={() => {
          void increment().catch(console.error);
        }}
      >
        Increment server
      </button>
      <p role="status">
        {isPending(count) ? 'Server value changing...' : 'Up to date'}
      </p>
    </Loading>
  );
}

render(() => <App />, document.getElementById('app'));
